// Port of node-semver v7 range matching with default options (not loose, no includePrerelease).

const NUM = "0|[1-9]\\d*";
const NUM_LOOSE = "\\d+";
const NON_NUM = "\\d*[a-zA-Z-][a-zA-Z0-9-]*";
const PRERELEASE = `(?:-((?:${NUM}|${NON_NUM})(?:\\.(?:${NUM}|${NON_NUM}))*))`;
const PRERELEASE_LOOSE = `(?:-?((?:${NUM_LOOSE}|${NON_NUM})(?:\\.(?:${NUM_LOOSE}|${NON_NUM}))*))`;
const BUILD = "(?:\\+([0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))";
const FULL_PLAIN = `v?(${NUM})\\.(${NUM})\\.(${NUM})${PRERELEASE}?${BUILD}?`;
const LOOSE_PLAIN = `[v=\\s]*(${NUM_LOOSE})\\.(${NUM_LOOSE})\\.(${NUM_LOOSE})${PRERELEASE_LOOSE}?${BUILD}?`;
const XID = `${NUM}|x|X|\\*`;
const XRANGE_PLAIN = `[v=\\s]*(${XID})(?:\\.(${XID})(?:\\.(${XID})(?:${PRERELEASE})?${BUILD}?)?)?`;
const GTLT = "((?:<|>)?=?)";

const FULL_RE = new RegExp(`^${FULL_PLAIN}$`);
const COMPARATOR_RE = new RegExp(`^${GTLT}\\s*(${FULL_PLAIN})$|^$`);
const HYPHEN_RE = new RegExp(`^\\s*(${XRANGE_PLAIN})\\s+-\\s+(${XRANGE_PLAIN})\\s*$`);
const COMPARATOR_TRIM_RE = new RegExp(`(\\s*)${GTLT}\\s*(${LOOSE_PLAIN}|${XRANGE_PLAIN})`, "g");
const TILDE_TRIM_RE = /(\s*)(?:~>?)\s+/g;
const CARET_TRIM_RE = /(\s*)(?:\^)\s+/g;
const TILDE_RE = new RegExp(`^(?:~>?)${XRANGE_PLAIN}$`);
const CARET_RE = new RegExp(`^(?:\\^)${XRANGE_PLAIN}$`);
const XRANGE_RE = new RegExp(`^${GTLT}\\s*${XRANGE_PLAIN}$`);
const BUILD_RE = new RegExp(BUILD);
const STAR_RE = /(<|>)?=?\s*\*/;
const GTE0_RE = /^\s*>=\s*0\.0\.0\s*$/;
const MAX_LENGTH = 256;

type Identifier = string | number;
type SemVer = { major: number; minor: number; patch: number; prerelease: Identifier[]; version: string };
type Operator = "" | "<" | "<=" | ">" | ">=";
type Comparator = { operator: Operator; semver: SemVer | null; value: string };

function parseVersion(input: string): SemVer | null {
  if (input.length > MAX_LENGTH) return null;
  const m = input.trim().match(FULL_RE);
  if (!m) return null;
  const [major, minor, patch] = [Number(m[1]), Number(m[2]), Number(m[3])];
  if (major > Number.MAX_SAFE_INTEGER || minor > Number.MAX_SAFE_INTEGER || patch > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  const prerelease: Identifier[] = m[4]
    ? m[4].split(".").map((id) => {
        const n = Number(id);
        return /^[0-9]+$/.test(id) && n < Number.MAX_SAFE_INTEGER ? n : id;
      })
    : [];
  const version = `${major}.${minor}.${patch}${prerelease.length ? `-${prerelease.join(".")}` : ""}`;
  return { major, minor, patch, prerelease, version };
}

function compareIdentifiers(a: Identifier, b: Identifier): number {
  const aNum = /^[0-9]+$/.test(String(a));
  const bNum = /^[0-9]+$/.test(String(b));
  if (aNum && bNum) {
    a = Number(a);
    b = Number(b);
  }
  if (a === b) return 0;
  if (aNum && !bNum) return -1;
  if (bNum && !aNum) return 1;
  return a < b ? -1 : 1;
}

function compare(a: SemVer, b: SemVer): number {
  const main =
    compareIdentifiers(a.major, b.major) || compareIdentifiers(a.minor, b.minor) || compareIdentifiers(a.patch, b.patch);
  if (main) return main;
  if (a.prerelease.length && !b.prerelease.length) return -1;
  if (!a.prerelease.length && b.prerelease.length) return 1;
  for (let i = 0; ; i++) {
    const x = a.prerelease[i];
    const y = b.prerelease[i];
    if (x === undefined && y === undefined) return 0;
    if (y === undefined) return 1;
    if (x === undefined) return -1;
    if (x === y) continue;
    return compareIdentifiers(x, y);
  }
}

function isX(id: string | undefined): boolean {
  return !id || id.toLowerCase() === "x" || id === "*";
}

function hyphenReplace(...g: (string | undefined)[]): string {
  let [, from, fM, fm, fp, fpr, , to, tM, tm, tp, tpr] = g as string[];
  if (isX(fM)) from = "";
  else if (isX(fm)) from = `>=${fM}.0.0`;
  else if (isX(fp)) from = `>=${fM}.${fm}.0`;
  else from = `>=${from}`;

  if (isX(tM)) to = "";
  else if (isX(tm)) to = `<${+tM + 1}.0.0-0`;
  else if (isX(tp)) to = `<${tM}.${+tm + 1}.0-0`;
  else if (tpr) to = `<=${tM}.${tm}.${tp}-${tpr}`;
  else to = `<=${to}`;
  return `${from} ${to}`.trim();
}

function replaceCaret(comp: string): string {
  return comp.replace(CARET_RE, (_, M: string, m: string, p: string, pr: string) => {
    if (isX(M)) return "";
    if (isX(m)) return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    if (isX(p)) {
      if (M === "0") return `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
      return `>=${M}.${m}.0 <${+M + 1}.0.0-0`;
    }
    const lower = pr ? `>=${M}.${m}.${p}-${pr}` : `>=${M}.${m}.${p}`;
    if (M !== "0") return `${lower} <${+M + 1}.0.0-0`;
    if (m !== "0") return `${lower} <${M}.${+m + 1}.0-0`;
    return `${lower} <${M}.${m}.${+p + 1}-0`;
  });
}

function replaceTilde(comp: string): string {
  return comp.replace(TILDE_RE, (_, M: string, m: string, p: string, pr: string) => {
    if (isX(M)) return "";
    if (isX(m)) return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    if (isX(p)) return `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
    if (pr) return `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`;
    return `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`;
  });
}

function replaceXRange(comp: string): string {
  return comp.trim().replace(XRANGE_RE, (whole, gtlt: string, M: string, m: string, p: string) => {
    const xM = isX(M);
    const xm = xM || isX(m);
    const anyX = xm || isX(p);
    if (gtlt === "=" && anyX) gtlt = "";
    if (xM) return gtlt === ">" || gtlt === "<" ? "<0.0.0-0" : "*";
    if (gtlt && anyX) {
      let [major, minor, patch] = [+M, xm ? 0 : +m, 0];
      let pr = "";
      if (gtlt === ">") {
        gtlt = ">=";
        if (xm) {
          major += 1;
          minor = 0;
        } else {
          minor += 1;
        }
      } else if (gtlt === "<=") {
        gtlt = "<";
        if (xm) major += 1;
        else minor += 1;
      }
      if (gtlt === "<") pr = "-0";
      return `${gtlt}${major}.${minor}.${patch}${pr}`;
    }
    if (xm) return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    if (anyX) return `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
    return whole;
  });
}

function parseComparatorText(comp: string): string {
  comp = comp.replace(BUILD_RE, "");
  comp = comp.trim().split(/\s+/).map(replaceCaret).join(" ");
  comp = comp.trim().split(/\s+/).map(replaceTilde).join(" ");
  comp = comp.split(/\s+/).map(replaceXRange).join(" ");
  return comp.trim().replace(STAR_RE, "");
}

function parseComparator(comp: string): Comparator | null {
  const m = comp.match(COMPARATOR_RE);
  if (!m) return null;
  const operator = (m[1] === "=" ? "" : (m[1] ?? "")) as Operator;
  if (!m[2]) return { operator, semver: null, value: "" };
  const semver = parseVersion(m[2]);
  if (!semver) return null;
  return { operator, semver, value: operator + semver.version };
}

function parseComparatorSet(range: string): Comparator[] | null {
  range = range.replace(HYPHEN_RE, hyphenReplace);
  range = range.replace(COMPARATOR_TRIM_RE, "$1$2$3");
  range = range.replace(TILDE_TRIM_RE, "$1~");
  range = range.replace(CARET_TRIM_RE, "$1^");
  const texts = range
    .split(" ")
    .map(parseComparatorText)
    .join(" ")
    .split(/\s+/)
    .map((comp) => comp.trim().replace(GTE0_RE, ""));

  const byValue = new Map<string, Comparator>();
  for (const text of texts) {
    const comparator = parseComparator(text);
    if (!comparator) return null;
    if (comparator.value === "<0.0.0-0") return [comparator];
    byValue.set(comparator.value, comparator);
  }
  if (byValue.size > 1) byValue.delete("");
  return [...byValue.values()];
}

function parseRange(range: string): Comparator[][] | null {
  const raw = range.trim().replace(/\s+/g, " ");
  let sets: Comparator[][] = [];
  for (const part of raw.split("||")) {
    const set = parseComparatorSet(part.trim());
    if (!set) return null;
    if (set.length) sets.push(set);
  }
  if (!sets.length) return null;
  if (sets.length > 1) {
    const first = sets[0];
    sets = sets.filter((set) => set[0].value !== "<0.0.0-0");
    if (!sets.length) return [first];
    const any = sets.find((set) => set.length === 1 && set[0].value === "");
    if (sets.length > 1 && any) return [any];
  }
  return sets;
}

function testComparator(c: Comparator, v: SemVer): boolean {
  if (!c.semver) return true;
  const order = compare(v, c.semver);
  switch (c.operator) {
    case "":
      return order === 0;
    case "<":
      return order < 0;
    case "<=":
      return order <= 0;
    case ">":
      return order > 0;
    case ">=":
      return order >= 0;
  }
}

function testSet(set: Comparator[], v: SemVer): boolean {
  if (!set.every((c) => testComparator(c, v))) return false;
  if (!v.prerelease.length) return true;
  return set.some(
    (c) =>
      c.semver !== null &&
      c.semver.prerelease.length > 0 &&
